// ============================================================================
// RLE4K Decoder Core Module
// ============================================================================
// Description: Main decoder module integrating all sub-modules
//              - Input FIFO (32-bit → 8-bit)
//              - Code Parser
//              - Bit Mode Decoder (Mask LUT)
//              - Segment Mode Decoder (Direct Generation)
//              - Output Accumulator (Variable → 512-bit)
// Author: Generated by Claude Code
// Date: 2026-01-09
// ============================================================================

`timescale 1ns / 1ps

module rle4k_decoder_core (
    input  wire        clk,
    input  wire        rst_n,

    // Input: Compressed data stream (32-bit AXI-Stream)
    input  wire [31:0] encoded_data_in,
    input  wire        encoded_data_valid,      // Data valid signal (per data word)
    input  wire        block_start,          // Block start signal (pulse, one cycle)
    input  wire        stream_end,           // Stream end signal (pulse): all compressed data sent
    output wire        decoder_fifo_ready,

    // Output: Decoded data stream (512-bit AXI-Stream)
    output wire [511:0] decoded_data_out,
    output wire         word_decoded_valid,
    input  wire         word_decoded_ready,

    // Configuration: Block parameters
    // - Block index: Used to calculate the starting address of this tile in DDR4
    // - Line width: Used to determine when to end a line (line end detection)
    // - Line stride: 512-bit aligned stride, used for DDR4 address calculation (output for system)
    // - Block height: Total number of lines in this tile, used to determine when tile decoding is complete
    input  wire [31:0] cfg_block_index,    // Block index, used for DDR4 starting address calculation
    input  wire [31:0] cfg_line_width,     // Line width in pixels (bits), e.g., 1920, 65536
    input  wire [31:0] cfg_line_stride,      // Line stride in bits (512-bit aligned), e.g., 2048, 65536
    input  wire [31:0] cfg_block_height,   // Block height in lines, e.g., 1080
    // Total lines in strip (= STREAM_START total_height); strip_end_out when counted line-ends reach this.
    input  wire [31:0] cfg_strip_line_count,
    // Logical RLE compressed byte count for this strip (excludes 0..3 wire-alignment 0x00 after payload).
    input  wire [31:0] cfg_rle_payload_bytes,
    // One-cycle pulse (125 MHz): reset byte index when new STREAM_START config is applied (CDC from adapter).
    input  wire        strip_byte_cnt_rst,
    // High while payload is still queued upstream of this module (adapter feed state,
    // CDC FIFO, top-level skid). Only used to hold off STREAM_END zero fill; tie low in
    // benches that drive encoded_data_in directly with no buffering in front.
    input  wire        upstream_busy,

    // Status signals (for system integration, not needed in testbench)
    output wire [31:0] decode_status,
    output wire        block_done,          // Frame decoding complete (all lines decoded)
    output wire        strip_end_out,       // Strip complete (cfg_strip_line_count lines) — CRC latch in top
    output wire [31:0] block_index_out,     // Block index output (for system layer DDR4 address calculation)

    // Observation only, never read by the design. decode_status already carries the
    // per-block line counter and output_line_end, but not the strip-scope counter that
    // actually gates strip_end_out, nor the accumulator state behind a line end. Without
    // both sides an ILA can only prove half of a line-end miscount.
    output wire [31:0] dbg_core
);

// ============================================================================
// Internal Signals
// ============================================================================

// FIFO 32→8 signals (raw) and gated path to code parser (strip tail 0x00 must not enter RLE parser)
wire [7:0]  fifo_code_byte;
wire        fifo_code_valid;
wire        fifo_code_ready;
wire [7:0]  code_byte;
wire        code_byte_valid;
wire        code_byte_ready;

reg  [31:0] stream_byte_idx;
wire        in_rle_payload = (stream_byte_idx < cfg_rle_payload_bytes);

assign fifo_code_ready = fifo_code_valid && (
    (in_rle_payload && code_byte_ready) ||
    (!in_rle_payload)
);
assign code_byte        = fifo_code_byte;
assign code_byte_valid  = fifo_code_valid && in_rle_payload;

always @(posedge clk) begin
    if (!rst_n)
        stream_byte_idx <= 32'd0;
    else if (strip_byte_cnt_rst)
        stream_byte_idx <= 32'd0;
    else if (fifo_code_valid && fifo_code_ready)
        stream_byte_idx <= stream_byte_idx + 32'd1;
end

// Code parser signals
wire        parsed_valid;
wire        parsed_ready;       // Ready signal from run dispatcher
wire        code_color;
wire [11:0] code_length;        // Unified length: 1-4032 bits
// run dispatcher signals
reg         decoder_ready;       // Ready signal from run dispatcher
reg         decoder_output_valid;
reg [511:0] decoder_output_data;
reg [9:0]   decoder_output_length;
reg         decoder_output_line_end;

// Line end padding signals
reg         padding_output_valid;
reg [511:0] padding_output_data;
reg [9:0]   padding_output_length;

// Merged output signals
wire        accumulator_output_valid;
wire [511:0] accumulator_output_data;
wire [9:0]  accumulator_output_length;
wire        merged_output_line_end;
wire        accumulator_output_ready;   // Ready signal from output Accumulator

// Line tracking signals
reg [31:0]  line_bits_counter;   // Current line bits counter (0 to stride)
reg         need_line_end_padding;  // Need to generate line end padding
reg [31:0]  line_end_padding_length; // Padding length for line end
reg         need_line_end_padding_pending;  // Pending flag: set need_line_end_padding after data accepted
reg [31:0]  line_end_padding_length_pending; // Pending padding length

// Data accumulator accumulated_bits signal
wire [9:0]  accumulated_bits;  // Current accumulated bits in accumulator (0-512)

// Output line end signal (generated by core based on width)
reg         output_line_end;
reg         line_end_occurred;  // Flag to signal line end when padding_length = 0
reg         padding_completed;  // Flag to signal padding completed, wait for accumulator to flush

// Stream end fill logic: after all compressed data received, pad remaining lines with zeros
reg         stream_end_received;    // Latched stream_end signal
reg         stream_end_filling;     // Currently filling remaining lines with zeros
reg [31:0]  fill_line_bits_remaining; // Bits remaining in current fill line

// Forward declaration: block_done_reg is defined in the Block Done section below,
// but referenced earlier in the stream_end fill activation guard.
reg         block_done_reg;

// Strip complete (cfg-only): asserted when decoded line-end count reaches cfg_strip_line_count
reg         strip_end_reg;
reg         block_done_reg_d1;      // edge detect for stream_end_filling cleanup

// ---------------------------------------------------------------------------
// STREAM_END drain interlock
// ---------------------------------------------------------------------------
// STREAM_END means "the host has no more payload", not "stop decoding now". Entering
// zero fill while payload is still queued silently replaces the tail of the strip with
// zeros; on the board that cost about 24 lines per strip and showed up only as a small
// word-count offset (reports/2026-08-09-stream-end-race-root-cause.md).
//
// drain_pending covers every stage that can still be holding real payload:
//   upstream_busy   - adapter feed state machine, CDC FIFO and top-level skid register,
//                     none of which this module can see (driven from rle4k_lan_top_v8)
//   input_fifo_busy - the 32->8 FIFO, its prefetch register and its active word
//   fifo_code_valid - a code byte presented but not yet consumed
//   parsed_valid    - a parsed code sitting at the decoder input
//   remaining_length- a run currently being emitted (already covered at :413)
//
// The interlock is released by a no-progress watchdog rather than a flat timeout. A flat
// timeout would have to be sized against worst-case data expansion (one code byte can
// expand to a full 65536-bit line, so a few kB of queued payload can legitimately take
// milliseconds) and would then be too coarse to catch a real stall. Progress here is any
// byte consumed or any word emitted, so a legitimate slow drain never trips it however
// long it takes, while a stall - which this design can genuinely produce, since frames
// are still dropped at line rate - is bounded at DRAIN_STALL_LIMIT cycles. Without a
// fallback the strip would never end and the host would hang, which is worse than the
// defect being fixed.
// The adapter serialises datagrams, so every payload byte has already been pushed into
// the CDC FIFO by the time it dispatches STREAM_END. The stream_end pulse and the FIFO
// write pointer cross into this clock domain on separate synchronisers though, so the
// FIFO can still read empty for a few cycles after the pulse lands. DRAIN_QUIET_CYCLES
// makes the interlock wait out that window instead of trusting a single-cycle sample.
localparam integer DRAIN_QUIET_CYCLES = 16;
localparam integer DRAIN_STALL_LIMIT  = 65536;  // 0.52 ms at 125 MHz with zero progress
wire        input_fifo_busy;
reg  [16:0] drain_stall_cnt;
reg  [5:0]  drain_quiet_cnt;
wire        drain_progress;
wire        drain_pending;
wire        drain_timeout = (drain_stall_cnt >= DRAIN_STALL_LIMIT);
wire        drain_clear   = (drain_quiet_cnt >= DRAIN_QUIET_CYCLES) || drain_timeout;

// Parameter validation and error code
reg  [7:0]  error_code;         // Error code: 0x00=OK, 0x01=EmptyData, 0x03=ParamError, 0x04=DataSizeMismatch
reg         param_error_flag;   // Parameter error detected flag
reg         data_size_mismatch_flag;  // Data size mismatch detected flag (set in decoder, cleared in block_done)

// ============================================================================
// Module 1: Input FIFO (32-bit → 8-bit)
// ============================================================================

input_fifo_32to8 u_input_fifo (
    .clk          (clk),
    .rst_n        (rst_n),

    // 32-bit input
    .data_in      (encoded_data_in),
    .valid_in     (encoded_data_valid),
    .ready_out    (decoder_fifo_ready),

    // 8-bit output
    .data_out     (fifo_code_byte),
    .valid_out    (fifo_code_valid),
    .ready_in     (fifo_code_ready),
    .busy         (input_fifo_busy)
);

// ============================================================================
// Module 2: Code Parser
// ============================================================================

rle4k_decoder_code_parser u_code_parser (
    .clk            (clk),
    .rst_n          (rst_n),

    // Input
    .code_in        (code_byte),
    .code_valid_in  (code_byte_valid),
    .code_ready     (code_byte_ready),

    // Output
    .parsed_ready   (parsed_ready),
    .parsed_valid   (parsed_valid),
    .code_color     (code_color),
    .code_length    (code_length)
);

// ============================================================================
// Module 3: run dispatcher (Unified processing for all modes)
// ============================================================================
// run dispatcher: directly generates data based on code_color and code_length
// No distinction between bit mode and segment mode

reg [11:0] remaining_length;      // Remaining length to output
reg        decoder_code_color_reg; // Store code_color for multi-cycle output

// Temporary variables for calculations
reg [31:0] calc_send_length;
reg [31:0] calc_effective_length;
reg        calc_need_split;
reg [31:0] new_line_bits_counter;  // Temporary for checking new counter value

// Generate 512-bit all zeros or all ones data
// Use decoder_code_color_reg for remaining_length processing
// Use code_color directly for new code processing
wire [511:0] decoder_data_full = decoder_code_color_reg ? 
    {512{1'b1}}: 
    512'd0;
wire [511:0] decoder_data_new = code_color ? {512{1'b1}}: 512'd0;

always @(posedge clk) begin
    if (!rst_n) begin
        decoder_output_valid  <= 1'b0;
        decoder_output_data   <= 512'd0;
        decoder_output_length <= 10'd0;
        decoder_output_line_end <= 1'b0;
        decoder_ready         <= 1'b1;
        remaining_length     <= 12'd0;
        decoder_code_color_reg <= 1'b0;
        line_bits_counter    <= 32'd0;
        need_line_end_padding <= 1'b0;
        line_end_padding_length <= 32'd0;
        need_line_end_padding_pending <= 1'b0;
        line_end_padding_length_pending <= 32'd0;
        padding_output_valid <= 1'b0;
        padding_output_data  <= 512'd0;
        padding_output_length <= 10'd0;
        line_end_occurred <= 1'b0;
        padding_completed <= 1'b0;
        data_size_mismatch_flag <= 1'b0;
        stream_end_received <= 1'b0;
        stream_end_filling  <= 1'b0;
        drain_stall_cnt     <= 17'd0;
        drain_quiet_cnt     <= 6'd0;
        fill_line_bits_remaining <= 32'd0;
        block_done_reg_d1 <= 1'b0;
        // error_code moved to block_done always block
        // param_error_flag moved to block_done always block
    end else begin
        decoder_output_valid <= 1'b0;
        padding_output_valid <= 1'b0;
        // Don't clear line_end_occurred here - it will be cleared after output_line_end is generated
        // This ensures output_line_end generation logic can detect it
        padding_completed <= 1'b0;  // Clear flag at start of each cycle (will be set when padding completes)
        
        // Unified line end padding handler (priority: output padding first)
        // All three line end cases (is_line_end, width-based, length overflow) use this unified handler
        // Data accumulator handles break logic, we only need to check ready signal
        // IMPORTANT: Must be part of the same if-else chain to prevent duplicate data output
        if (need_line_end_padding && accumulator_output_ready) begin
            if (line_end_padding_length > 32'd0) begin
                // Send length: min(padding_length, 512) - accumulator handles break logic
                calc_send_length = (line_end_padding_length > 32'd512) ? 32'd512 : line_end_padding_length;
                
                padding_output_valid <= 1'b1;
                padding_output_data  <= 512'd0;  // Line end padding is always 0
                padding_output_length <= calc_send_length[9:0];
                
                line_bits_counter <= line_bits_counter + calc_send_length;
                
                if (line_end_padding_length > calc_send_length) begin
                    line_end_padding_length <= line_end_padding_length - calc_send_length;
                end else begin
                    // Padding completed, reset counter for new line
                    need_line_end_padding <= 1'b0;
                    line_end_padding_length <= 32'd0;
                    line_bits_counter <= 32'd0;  // Reset for new line
                    decoder_ready <= 1'b1;  // Ready for next code after padding completed
                    // Set padding_completed flag to signal padding is done
                    // output_line_end will be triggered when all data is flushed from accumulator
                    padding_completed <= 1'b1;
                end
            end else begin
                // Padding length = 0, no actual padding needed, just reset
                need_line_end_padding <= 1'b0;
                line_bits_counter <= 32'd0;
                decoder_ready <= 1'b1;  // Ready for next code
                line_end_occurred <= 1'b1;  // Signal that line end occurred (for output_line_end)
            end
        end
        // Handle new code from parser (only when not padding and no parameter error) - MUST use else if to be mutually exclusive
        else if (parsed_valid && decoder_ready && !need_line_end_padding && !param_error_flag && !stream_end_filling) begin
            // No in-band 0x00/0x40/0x80/0xC0 line/block/strip markers (V1.0 cfg delimiters only).
            if (code_length == 12'd0) begin
                decoder_ready <= 1'b1;
            end else begin
                // Normal code: check if length >= width, need to add line end
                calc_effective_length = code_length;
                calc_need_split = (cfg_line_width > 0) && (line_bits_counter + code_length >= cfg_line_width);
                
                // Check for data size mismatch: code_length exceeds remaining line width significantly
                // Error 0x04: DataSizeMismatch (when single code length > line_width)
                // Set flag to communicate with block_done always block
                if (cfg_line_width > 0 && code_length > cfg_line_width && line_bits_counter == 32'd0) begin
                    data_size_mismatch_flag <= 1'b1;  // Set flag, error_code assigned in block_done always block
                end
                
                if (calc_need_split) begin
                    // Split: truncate to width, remaining data within width still needs to be output
                    // Only data beyond width is discarded (silent), handled by not carrying over to next line
                    calc_effective_length = cfg_line_width - line_bits_counter;
                end
                decoder_code_color_reg <= code_color;
                // Note: remaining_length is set below based on calc_effective_length vs calc_send_length
                // For data within effective_length that exceeds 512 bits, it will be output in subsequent cycles
                
                // Calculate send length: min(effective_length, 512) - accumulator handles break logic
                calc_send_length = (calc_effective_length > 32'd512) ? 32'd512 : calc_effective_length;
                
                decoder_output_valid <= 1'b1;
                decoder_output_data  <= decoder_data_new;  // Use new code_color directly, not decoder_code_color_reg
                decoder_output_length <= calc_send_length[9:0];
                
                // Update line_bits_counter and check if we reached width
                new_line_bits_counter = line_bits_counter + calc_send_length;
                line_bits_counter <= new_line_bits_counter;
                
                if (calc_effective_length > calc_send_length) begin
                    // Need to break and continue in next cycle
                    // Continue outputting remaining data to reach width
                    remaining_length <= calc_effective_length - calc_send_length;  // Direct assignment, not accumulation
                    decoder_ready <= 1'b0;
                    // If split, set padding flag when data output completes (handled in remaining_length processing)
                end else begin
                    // This part of data is complete
                    // Use pending mechanism to delay padding activation until data is accepted
                    // This prevents the gate logic (original_data_valid = decoder_output_valid && !need_line_end_padding)
                    // from blocking the current data output
                    if (calc_need_split) begin
                        need_line_end_padding_pending <= 1'b1;
                        line_end_padding_length_pending <= cfg_line_stride - cfg_line_width;
                        decoder_ready <= 1'b0;
                    end else if ((cfg_line_width > 0) && (new_line_bits_counter >= cfg_line_width)) begin
                        need_line_end_padding_pending <= 1'b1;
                        line_end_padding_length_pending <= cfg_line_stride - cfg_line_width;
                        decoder_ready <= 1'b0;
                    end else begin
                        decoder_ready <= 1'b1;
                    end
                end
            end
        end else if (remaining_length > 12'd0 && accumulator_output_ready && !need_line_end_padding) begin
            // Continue outputting remaining data
            // Send length: min(remaining_length, 512) - accumulator handles break logic
            calc_send_length = (remaining_length > 12'd512) ? 32'd512 : remaining_length;
            
            decoder_output_valid <= 1'b1;
            decoder_output_data  <= decoder_data_full;
            decoder_output_length <= calc_send_length[9:0];
            
            // Update line_bits_counter and check if we reached width
            new_line_bits_counter = line_bits_counter + calc_send_length;
            line_bits_counter <= new_line_bits_counter;
            
            if (remaining_length > calc_send_length) begin
                remaining_length <= remaining_length - calc_send_length;
            end else begin
                remaining_length <= 12'd0;
                
                // Width-based line end: check if we reached width and need padding (width to stride)
                // Use pending flag to delay setting need_line_end_padding until data is accepted
                // This prevents the gate logic from blocking the current data output
                if ((cfg_line_width > 0) && (new_line_bits_counter >= cfg_line_width)) begin
                    need_line_end_padding_pending <= 1'b1;
                    line_end_padding_length_pending <= cfg_line_stride - cfg_line_width;
                    decoder_ready <= 1'b0;
                end else begin
                    decoder_ready <= 1'b1;
                end
            end
        end else if (decoder_output_valid && accumulator_output_ready) begin
            // Output accepted, clear valid and check if ready for next
            decoder_output_valid <= 1'b0;
            
            // Check pending flag and activate padding mode
            if (need_line_end_padding_pending) begin
                need_line_end_padding <= 1'b1;
                line_end_padding_length <= line_end_padding_length_pending;
                need_line_end_padding_pending <= 1'b0;
                decoder_ready <= 1'b0;  // Block until padding starts
            end else if (remaining_length == 12'd0 && !need_line_end_padding) begin
                decoder_ready <= 1'b1;
            end
        end
        // Stream-end zero fill: when all compressed data has been received but decoder
        // has not yet completed all lines, fill remaining bits/lines with zeros.
        // This activates only when the normal decode pipeline is idle.
        else if (stream_end_filling && !block_done_reg && !need_line_end_padding && remaining_length == 12'd0 
                 && !decoder_output_valid && !padding_output_valid && accumulator_output_ready) begin
            if (fill_line_bits_remaining > 32'd0) begin
                calc_send_length = (fill_line_bits_remaining > 32'd512) ? 32'd512 : fill_line_bits_remaining;
                padding_output_valid  <= 1'b1;
                padding_output_data   <= 512'd0;
                padding_output_length <= calc_send_length[9:0];
                line_bits_counter     <= line_bits_counter + calc_send_length;
                fill_line_bits_remaining <= fill_line_bits_remaining - calc_send_length;
            end else begin
                // Current fill line completed; this will be caught by
                // padding_completed / line_end_occurred in the line-end detection block,
                // and decoded_block_line_count will increment.
                // Next cycle, if block_done hasn't fired, we reload fill_line_bits_remaining
                // for the next line.
                padding_completed <= 1'b1;
                line_bits_counter <= 32'd0;
                fill_line_bits_remaining <= cfg_line_stride;
            end
        end
        
        // Latch stream_end pulse (can arrive any time, including mid-decode)
        if (stream_end) begin
            stream_end_received <= 1'b1;
        end
        
        // Watchdog for the drain interlock below. Only runs once STREAM_END is latched,
        // and any forward progress resets it, so it measures a genuine stall and not a
        // slow decode.
        if (!stream_end_received || !drain_pending || drain_progress)
            drain_stall_cnt <= 17'd0;
        else if (!drain_timeout)
            drain_stall_cnt <= drain_stall_cnt + 17'd1;

        if (drain_pending)
            drain_quiet_cnt <= 6'd0;
        else if (drain_quiet_cnt < DRAIN_QUIET_CYCLES)
            drain_quiet_cnt <= drain_quiet_cnt + 6'd1;

        // Activate fill mode when normal pipeline drains and stream_end has been received
        if (stream_end_received && !stream_end_filling && !block_done_reg
            && !need_line_end_padding && remaining_length == 12'd0
            && !decoder_output_valid && !padding_output_valid
            && drain_clear) begin
            stream_end_filling <= 1'b1;
            decoder_ready <= 1'b0;
            // If currently mid-line, pad rest of current line first
            if (line_bits_counter > 32'd0 && cfg_line_stride > line_bits_counter) begin
                fill_line_bits_remaining <= cfg_line_stride - line_bits_counter;
            end else begin
                // At line boundary already, start a fresh full line
                line_bits_counter <= 32'd0;
                fill_line_bits_remaining <= cfg_line_stride;
            end
        end
        
        // End stream-end fill when current block completes (no post-block marker drain).
        block_done_reg_d1 <= block_done_reg;
        if (block_done_reg && !block_done_reg_d1 && stream_end_filling) begin
            stream_end_filling  <= 1'b0;
            stream_end_received <= 1'b0;
            fill_line_bits_remaining <= 32'd0;
        end
        
        // Full decoder state reset on new block_start
        if (block_start) begin
            // Stream/fill state
            stream_end_received <= 1'b0;
            stream_end_filling  <= 1'b0;
            fill_line_bits_remaining <= 32'd0;
            // Run dispatcher state
            remaining_length <= 12'd0;
            decoder_code_color_reg <= 1'b0;
            line_bits_counter <= 32'd0;
            need_line_end_padding <= 1'b0;
            line_end_padding_length <= 32'd0;
            need_line_end_padding_pending <= 1'b0;
            line_end_padding_length_pending <= 32'd0;
            decoder_output_valid <= 1'b0;
            padding_output_valid <= 1'b0;
            line_end_occurred <= 1'b0;
            padding_completed <= 1'b0;
            data_size_mismatch_flag <= 1'b0;
            decoder_ready <= 1'b1;
        end
        
        // Clear padding_completed flag when output_line_end is triggered
        // This ensures padding_completed is cleared after output_line_end is set
        if (padding_completed && accumulated_bits == 10'd0 && !word_decoded_valid) begin
            padding_completed <= 1'b0;  // Clear flag after all data is flushed
        end
        
        // Clear line_end_occurred flag when output_line_end is generated
        // This ensures line_end_occurred is cleared after output_line_end is set
        if (output_line_end && line_end_occurred) begin
            line_end_occurred <= 1'b0;  // Clear flag after output_line_end is generated
        end
    end
end

// ============================================================================
// Parsed Ready Signal
// ============================================================================
assign parsed_ready = decoder_ready && !need_line_end_padding && !param_error_flag && !stream_end_filling;

assign drain_pending  = upstream_busy || input_fifo_busy || fifo_code_valid || parsed_valid;
assign drain_progress = (fifo_code_valid && fifo_code_ready) ||
                        (parsed_valid && parsed_ready) ||
                        decoder_output_valid || padding_output_valid;

// ============================================================================
// Module 4: Output Merge Logic
// ============================================================================
// Merge outputs from run dispatcher and line end padding
// According to document: original_data_valid = decoder_output_valid, padding_data_valid = padding_output_valid
// Priority: original_data and padding_data are mutually exclusive

// Gate decoder_output_valid when in padding mode to prevent duplicate data reception
// When need_line_end_padding=1, the old decoder_output_valid from previous cycle should be ignored
wire original_data_valid = decoder_output_valid && !need_line_end_padding;
wire [511:0] original_data = decoder_output_data;
wire [9:0] original_data_length = decoder_output_length;

wire padding_data_valid = padding_output_valid;
wire [511:0] padding_data = padding_output_data;
wire [9:0] padding_data_length = padding_output_length;

// Must not gate valid_in with block_done_reg: ready_out can stay high while valid_in is forced low,
// so the run-dispatcher branch (decoder_output_valid && accumulator_output_ready) falsely completes
// handshakes and drops payload at multi-block boundaries (seen as short word_count vs PC).
assign accumulator_output_valid    = (original_data_valid | padding_data_valid);
assign accumulator_output_data     = original_data_valid ? original_data : padding_data;
assign accumulator_output_length   = original_data_valid ? original_data_length : padding_data_length;
assign merged_output_line_end = 1'b0;  // Line end is handled by data accumulator based on width

decoder_output_accumulator u_data_accumulator (
    .clk              (clk),
    .rst_n            (rst_n),
    .clear            (block_start),

    // Input: merged output
    .data_in          (accumulator_output_data),
    .data_length_in   (accumulator_output_length),
    .valid_in         (accumulator_output_valid),
    .ready_out        (accumulator_output_ready),  // Ready signal: allow upstream to write

    // Output: 512-bit to DDR4
    .data_out         (decoded_data_out),
    .valid_out        (word_decoded_valid),
    .ready_in         (word_decoded_ready),
    
    // Status feedback
    .accumulated_bits (accumulated_bits)  // Current accumulated bits in accumulator (0-512)
);

// ============================================================================
// Line End Detection (Width-based)
// ============================================================================
// Generate line_end signal when we complete a line (reach stride)
// According to document: output_line_end = 1 when padding completed
// Line end is detected when line_bits_counter resets to 0 after completing stride padding

always @(posedge clk) begin
    if (!rst_n) begin
        output_line_end <= 1'b0;
    end else begin
        output_line_end <= 1'b0;
        
        // Line end is detected in three cases:
        // 1. When padding completes and all data is flushed from accumulator
        // 2. When padding_length = 0 and we directly reset (line_end_occurred flag)
        // 3. Legacy case: when padding_output_valid accepted and padding done (for backward compatibility)
        
        // Case 1: Padding completed and all data flushed from accumulator
        // If accumulated_bits == 0, all data has been output
        // If accumulated_bits < 512, remaining data stays in accumulator (for next line), trigger immediately
        if (padding_completed && (accumulated_bits == 10'd0 || (accumulated_bits < 10'd512 && !word_decoded_valid))) begin
            output_line_end <= 1'b1;
        end
        
        // Case 2: Padding length = 0, direct reset (line_end_occurred set in main always block)
        // Note: line_end_occurred is set in the same cycle, so we can detect it here
        if (line_end_occurred) begin
            output_line_end <= 1'b1;
            // Clear line_end_occurred after output_line_end is generated
            // This must be done in the main always block, so we use a wire to signal it
        end
        
        // Case 3: Legacy case - when padding completes and last padding data is accepted
        // This triggers when padding_output_valid is accepted and padding is done
        // This is a fallback for cases where Case 1 might not trigger immediately
        if (padding_output_valid && accumulator_output_ready && 
            !need_line_end_padding && line_bits_counter == 32'd0) begin
            output_line_end <= 1'b1;
        end
    end
end

// ============================================================================
// Block Done Detection
// ============================================================================
// Block is done when all lines are decoded (based on cfg_block_height)

reg [31:0] decoded_block_line_count;
// block_done_reg declared above (forward declaration for stream_end fill guard)
reg        output_line_end_prev;  // Previous cycle value for edge detection
reg        block_start_prev;      // Previous cycle value for block_start edge detection
reg [31:0] strip_line_count;      // Lines finished in current strip (cfg-only strip_end_out)
reg [31:0] cfg_bi_when_idle;      // Last cfg_block_index while !block_done_reg (multi-block advance)

// TB / legacy: if cfg_strip_line_count==0, fall back to per-block height for single-block strips
wire [31:0] eff_strip_target = (cfg_strip_line_count != 32'd0) ? cfg_strip_line_count : cfg_block_height;

// Main clock domain: block_done, strip_end (cfg_strip_line_count), multi-block cfg index
always @(posedge clk) begin
    if (!rst_n) begin
        decoded_block_line_count <= 32'd0;
        block_done_reg <= 1'b0;
        output_line_end_prev <= 1'b0;
        block_start_prev <= 1'b0;
        error_code <= 8'h00;
        param_error_flag <= 1'b0;
        strip_line_count <= 32'd0;
        strip_end_reg <= 1'b0;
        cfg_bi_when_idle <= 32'd0;
    end else begin
        output_line_end_prev <= output_line_end;
        block_start_prev <= block_start;

        if (data_size_mismatch_flag) begin
            error_code <= 8'h04;
            param_error_flag <= 1'b1;
        end

        if (strip_byte_cnt_rst) begin
            decoded_block_line_count <= 32'd0;
            block_done_reg <= 1'b0;
            strip_line_count <= 32'd0;
            strip_end_reg <= 1'b0;
            cfg_bi_when_idle <= cfg_block_index;
        end else if (block_start && !block_start_prev) begin
            decoded_block_line_count <= 32'd0;
            if (cfg_line_width == 32'd0 && cfg_block_height == 32'd0) begin
                error_code <= 8'h01;
                param_error_flag <= 1'b1;
                block_done_reg <= 1'b1;
            end else if (cfg_line_width == 32'd0 || cfg_block_height == 32'd0 ||
                         cfg_line_stride == 32'd0 || cfg_line_stride < cfg_line_width) begin
                error_code <= 8'h03;
                param_error_flag <= 1'b1;
                block_done_reg <= 1'b1;
            end else begin
                error_code <= 8'h00;
                param_error_flag <= 1'b0;
                block_done_reg <= 1'b0;
            end
        end else begin
            if (block_done_reg && (cfg_block_index != cfg_bi_when_idle)) begin
                block_done_reg <= 1'b0;
                decoded_block_line_count <= 32'd0;
                cfg_bi_when_idle <= cfg_block_index;
            end else if (!block_done_reg) begin
                cfg_bi_when_idle <= cfg_block_index;
            end

            if (output_line_end && !output_line_end_prev && !param_error_flag) begin
                strip_line_count <= strip_line_count + 32'd1;
                if (eff_strip_target > 32'd0 &&
                    strip_line_count + 32'd1 >= eff_strip_target) begin
                    strip_end_reg <= 1'b1;
                end
                decoded_block_line_count <= decoded_block_line_count + 32'd1;
                if (decoded_block_line_count + 32'd1 >= cfg_block_height && cfg_block_height > 32'd0) begin
                    block_done_reg <= 1'b1;
                end
            end
        end
    end
end

assign block_done = block_done_reg;
assign strip_end_out = strip_end_reg;

// ============================================================================
// Block Index Output (for system layer DDR4 address calculation)
// ============================================================================

assign block_index_out = cfg_block_index;

// ============================================================================
// Decode Status (for system integration and debugging)
// ============================================================================
// Error code priority: If error_code != 0, return error_code in [7:0]
// Otherwise, return status bits in [7:0]
wire [7:0] status_low_byte;
assign status_low_byte = (error_code != 8'h00) ? error_code : {
    1'b0,              // [7] Bit mode active (deprecated, run dispatcher)
    parsed_valid,       // [6] Parser active (for system monitoring)
    code_byte_valid,    // [5] Code byte valid (for system monitoring)
    encoded_data_valid,   // [4] Input valid (for system monitoring)
    word_decoded_valid,      // [3] Output valid (for system monitoring)
    word_decoded_ready,      // [2] Output ready (for system monitoring)
    decoder_fifo_ready,   // [1] Input ready (for system monitoring)
    rst_n               // [0] Reset status (for system monitoring)
};

// [12] disambiguates the low byte: it is an error code only while this bit is
// set, otherwise the low byte is live status and 0x07 is a healthy idle value.
// Hosts that predate this bit see 0 and fall back to the other evidence.
wire error_present = (error_code != 8'h00);

assign decode_status = {
    decoded_block_line_count[15:0],  // [31:16] Lines decoded so far
    3'd0,               // [15:13] Reserved
    error_present,      // [12] Low byte carries an error code
    stream_end_received, // [11] STREAM_END latched (host); not in-band 0xC0
    stream_end_filling,  // [10] Zero-fill in progress
    output_line_end,    // [9] Line end flag
    block_done_reg,     // [8] Block done
    status_low_byte     // [7:0] Error code or status bits
};

assign dbg_core = {
    strip_end_reg,              // [31]
    param_error_flag,           // [30]
    accumulator_output_ready,   // [29]
    padding_output_valid,       // [28]
    line_end_occurred,          // [27]
    padding_completed,          // [26]
    accumulated_bits[9:0],      // [25:16]
    strip_line_count[15:0]      // [15:0] the counter strip_end_out actually compares
};

endmodule

// ============================================================================
// Sub-module: Input FIFO (32-bit -> 8-bit)
// ============================================================================
// Architecture:
//   - 16-deep FIFO for 32-bit words
//   - Prefetch register (next_reg) + active word register (hold_reg)
//   - data_out is a combinational byte mux out of hold_reg, so a byte can be
//     accepted every cycle including across a 32-bit word boundary
//
// The earlier version had a single holding register and a registered data_out,
// which cost two dead cycles at every word boundary (drain hold -> pop -> present)
// and a further cycle of latency at the head of a stream. The bypass path that
// hid that head latency is gone with it: every word now goes through fifo_mem,
// which also removes the read-during-write corner the bypass existed to dodge.

module input_fifo_32to8 (
    input  wire        clk,
    input  wire        rst_n,

    input  wire [31:0] data_in,
    input  wire        valid_in,
    output wire        ready_out,

    output wire [7:0]  data_out,
    output wire        valid_out,
    input  wire        ready_in,

    // High while any byte is still held anywhere in here. Needed so the strip tail
    // is not zero filled while real payload is still queued (see :413).
    output wire        busy
);

parameter FIFO_DEPTH      = 16;
parameter FIFO_DEPTH_LOG2 = 4;

reg [31:0] fifo_mem [0:FIFO_DEPTH-1];
reg [FIFO_DEPTH_LOG2-1:0] wr_ptr;
reg [FIFO_DEPTH_LOG2-1:0] rd_ptr;
reg [FIFO_DEPTH_LOG2:0]   occupancy;

integer rst_i;

wire fifo_full  = (occupancy == FIFO_DEPTH);
wire fifo_empty = (occupancy == 0);

// Active word being sliced into bytes, and the word prefetched behind it
reg [31:0] hold_reg;
reg        hold_valid;
reg [1:0]  byte_sel;
reg [31:0] next_reg;
reg        next_valid;

// busy must cover every register that can still be holding payload, otherwise the
// STREAM_END drain interlock in the core releases early and the strip tail gets
// zero filled (reports/2026-08-09-stream-end-race-root-cause.md). next_valid is
// the state the prefetch register adds; valid_out is hold_valid so hold_reg is
// covered by the hold_valid term.
assign busy = !fifo_empty | hold_valid | next_valid;

wire store_to_fifo = valid_in & ~fifo_full;

// Popping on the cycle a word is written would read fifo_mem before the write
// settles. occupancy is registered, so fifo_empty still reads 1 on that cycle and
// the pop is naturally deferred to the next one.
wire pop_fifo = ~fifo_empty & ~next_valid;

wire byte_accepted = valid_out & ready_in;
wire last_byte     = (byte_sel == 2'd3);

assign valid_out = hold_valid;
assign data_out  = (byte_sel == 2'd0) ? hold_reg[7:0]   :
                   (byte_sel == 2'd1) ? hold_reg[15:8]  :
                   (byte_sel == 2'd2) ? hold_reg[23:16] :
                                        hold_reg[31:24];

// Accept input when the FIFO has room. Purely registered, so there is no
// combinational path from valid_in back to ready_out.
assign ready_out = ~fifo_full;

always @(posedge clk) begin
    if (!rst_n) begin
        wr_ptr     <= 0;
        rd_ptr     <= 0;
        occupancy  <= 0;
        hold_reg   <= 32'd0;
        hold_valid <= 1'b0;
        byte_sel   <= 2'd0;
        next_reg   <= 32'd0;
        next_valid <= 1'b0;
        for (rst_i = 0; rst_i < FIFO_DEPTH; rst_i = rst_i + 1)
            fifo_mem[rst_i] <= 32'd0;
    end else begin

        // --- FIFO write ---
        if (store_to_fifo) begin
            fifo_mem[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1'b1;
        end

        // --- Prefetch: FIFO -> next_reg ---
        // pop_fifo requires ~next_valid, so this never races the hold refill below.
        if (pop_fifo) begin
            next_reg   <= fifo_mem[rd_ptr];
            next_valid <= 1'b1;
            rd_ptr     <= rd_ptr + 1'b1;
        end

        // --- Byte extraction, and refill of hold_reg from the prefetch ---
        if (byte_accepted && last_byte) begin
            if (next_valid) begin
                hold_reg   <= next_reg;
                hold_valid <= 1'b1;
                byte_sel   <= 2'd0;
                next_valid <= 1'b0;
            end else begin
                hold_valid <= 1'b0;
            end
        end else if (byte_accepted) begin
            byte_sel <= byte_sel + 1'b1;
        end else if (!hold_valid && next_valid) begin
            hold_reg   <= next_reg;
            hold_valid <= 1'b1;
            byte_sel   <= 2'd0;
            next_valid <= 1'b0;
        end

        // --- Occupancy ---
        if (store_to_fifo && !pop_fifo)
            occupancy <= occupancy + 1'b1;
        else if (!store_to_fifo && pop_fifo)
            occupancy <= occupancy - 1'b1;

    end
end

endmodule

